#[test]fn retirement_context_close_rejects_all_four_original_unconsumed_choices_without_writes(){
 for label in ["settings","companions","pet-control","pet-panel"]{
  let(f,store,g,decision)=initial("ollama",false);let mut cache=Reviews::default();let origin=Origin{window:label.into(),frame:crate::settings::review::Frame::fixture()};let ticket=cache.insert(&origin,review(&f,&store,&g,&decision,100_040),100_040).unwrap();let input=RetirementConfirmInput{pet_id:g.spec.owner.pet_id.clone(),goal_id:g.id.clone(),decision_id:decision.clone(),revision:g.revision.clone(),token:ticket.token.clone(),approve:true};let pending=cache.lookup(&origin,&input).unwrap();let before=inventory(&f.path);
  origin.frame.invalidate_for_test();assert!(matches!(pending.confirm(&store,true,100_041),Err(Error::Conflict)));let reopened=Origin{window:label.into(),frame:origin.frame.next_for_test()};assert!(cache.lookup(&reopened,&input).is_err());assert_eq!(inventory(&f.path),before);let next=cache.insert(&reopened,review(&f,&store,&g,&decision,100_042),100_042).unwrap();assert_ne!(next.token,ticket.token);assert_eq!(inventory(&f.path),before);assert_eq!(store.read(&g.id,&g.spec.owner.pet_id).unwrap().revision,g.revision);
 }
}
#[test]fn retirement_review_captured_before_wait_cannot_be_inserted_after_context_changed(){
 let(f,store,g,decision)=initial("ollama",false);let mut cache=Reviews::default();let origin=Origin{window:"settings".into(),frame:crate::settings::review::Frame::fixture()};let native=review(&f,&store,&g,&decision,100_040);let before=inventory(&f.path);origin.frame.invalidate_for_test();assert!(matches!(cache.insert(&origin,native,100_041),Err(Error::Conflict)));assert!(cache.pending.is_empty());assert_eq!(inventory(&f.path),before);
}
#[test]fn reopened_retirement_alias_has_one_shared_choice_and_original_time_through_seventy_reopens(){
 let(f,store,g,decision,mut cache,ticket,pending)=setup();let lock=OpenOptions::new().read(true).write(true).open(root(&f).join(".catalog.lock")).unwrap();assert_eq!(unsafe{libc::flock(lock.as_raw_fd(),libc::LOCK_SH|libc::LOCK_NB)},0);assert!(matches!(pending.confirm(&store,true,100_041).unwrap(),RetirementConfirmed::Blocked{reason:Error::Busy,retained:true,..}));
 let input=RetirementPrepareInput{pet_id:g.spec.owner.pet_id.clone(),goal_id:g.id.clone(),revision:g.revision.clone(),decision_id:decision.clone(),request_id:"reopened-retirement".into()};let mut current=pending.clone();let mut last=ticket.token;
 for _ in 0..70{
  current.origin.frame.invalidate_for_test();let origin=Origin{window:"settings".into(),frame:current.origin.frame.next_for_test()};let alias=cache.find(&origin,&input,&g,400_000).unwrap().unwrap();assert_ne!(alias.token,last);assert_eq!(alias.proposal.approval_scope,"confirmOriginalRetirement");assert_eq!(alias.proposal.prepared_at,100_040);assert_eq!(alias.proposal.expires_at,pending.ticket.proposal.expires_at);let choice=RetirementConfirmInput{pet_id:input.pet_id.clone(),goal_id:input.goal_id.clone(),revision:input.revision.clone(),decision_id:input.decision_id.clone(),token:alias.token.clone(),approve:true};let next=cache.lookup(&origin,&choice).unwrap();assert!(Arc::ptr_eq(&next.state,&pending.state));assert_eq!(cache.pending.len(),1);current=next;last=alias.token;
 }
 drop(lock);let receipt=match current.confirm(&store,true,400_001).unwrap(){RetirementConfirmed::Retired{receipt}=>receipt,_=>panic!("original native retirement must complete once")};assert_eq!(receipt.reference.approved_at,100_041);assert!(!receipt.execution_available&&!receipt.new_admission_created);let before=inventory(&f.path);current.confirm(&store,true,400_002).unwrap();assert_eq!(inventory(&f.path),before);
}
#[test]fn live_different_owner_with_the_same_label_cannot_claim_original_retirement(){
 let(f,store,g,decision,mut cache,_ticket,pending)=setup();let lock=OpenOptions::new().read(true).write(true).open(root(&f).join(".catalog.lock")).unwrap();assert_eq!(unsafe{libc::flock(lock.as_raw_fd(),libc::LOCK_SH|libc::LOCK_NB)},0);assert!(matches!(pending.confirm(&store,true,100_041).unwrap(),RetirementConfirmed::Blocked{retained:true,..}));let before=inventory(&f.path);let other=Origin{window:"settings".into(),frame:crate::settings::review::Frame::fixture()};let input=RetirementPrepareInput{pet_id:g.spec.owner.pet_id.clone(),goal_id:g.id.clone(),revision:g.revision.clone(),decision_id:decision,request_id:"foreign-owner".into()};assert!(matches!(cache.find(&other,&input,&g,100_042),Err(Error::Conflict)));assert_eq!(inventory(&f.path),before);drop(lock);
}
